package com.library.server.service.impl;
import com.library.common.constant.RoleConstant; import com.library.common.exception.BusinessException; import com.library.common.model.PageResult; import com.library.common.model.LoginUser; import com.library.pojo.dto.BorrowDTO; import com.library.pojo.dto.ReturnDTO; import com.library.pojo.entity.Book; import com.library.pojo.entity.BorrowRecord; import com.library.pojo.entity.Reader; import com.library.pojo.vo.BorrowVO; import com.library.server.mapper.BookMapper; import com.library.server.mapper.BorrowMapper; import com.library.server.mapper.ReaderMapper; import com.library.server.service.BorrowService; import com.library.server.util.UserContext; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.List;
@Service public class BorrowServiceImpl implements BorrowService { private final BorrowMapper borrowMapper;private final BookMapper bookMapper;private final ReaderMapper readerMapper; public BorrowServiceImpl(BorrowMapper b,BookMapper bm,ReaderMapper r){borrowMapper=b;bookMapper=bm;readerMapper=r;}
 @Transactional public void borrow(BorrowDTO dto){LoginUser user=UserContext.get();if(user!=null&&RoleConstant.READER.equals(user.getRole())&&!user.getId().equals(dto.readerId()))throw new BusinessException("不能为其他读者借书");Reader reader=readerMapper.findById(dto.readerId());if(reader==null||reader.getStatus()!=1)throw new BusinessException("读者不存在或已禁用");int maxBorrow=reader.getMaxBorrow()==null?5:reader.getMaxBorrow();if(readerMapper.countBorrowing(dto.readerId())>=maxBorrow)throw new BusinessException("已达到最大借阅数量");Book book=bookMapper.findById(dto.bookId());if(book==null||book.getAvailableStock()==null||book.getAvailableStock()<=0)throw new BusinessException("图书无可借库存");if(bookMapper.decreaseStock(dto.bookId())!=1)throw new BusinessException("库存更新失败");BorrowRecord r=new BorrowRecord();r.setReaderId(dto.readerId());r.setBookId(dto.bookId());r.setDueTime(LocalDateTime.now().plusDays(dto.days()==null?30:dto.days()));r.setStatus(1);r.setRemark(dto.remark());r.setOperatorId(user!=null&&RoleConstant.ADMIN.equals(user.getRole())?user.getId():null);borrowMapper.insert(r);}
 @Transactional public void returnBook(ReturnDTO dto){BorrowRecord r=borrowMapper.findById(dto.recordId());LoginUser user=UserContext.get();if(r==null||r.getStatus()!=1)throw new BusinessException("借阅记录不存在或已归还");if(user!=null&&RoleConstant.READER.equals(user.getRole())&&!user.getId().equals(r.getReaderId()))throw new BusinessException("不能归还其他读者的记录");r.setStatus(dto.status());r.setReturnTime(LocalDateTime.now());r.setRemark(dto.remark());if(borrowMapper.returnBook(r)!=1)throw new BusinessException("归还失败");bookMapper.increaseStock(r.getBookId());}
 public PageResult<BorrowVO> page(Long readerId,int page,int size){return new PageResult<>(borrowMapper.count(readerId),page,size,borrowMapper.page(readerId,(page-1)*size,size));} public List<BorrowVO> timeline(Long readerId){return borrowMapper.timeline(readerId);} }
